attempts.cypher:
MATCH (p:Pod)-[:BelongsTo]->(ns:Namespace)
WHERE ns['metadata']['name'] = 'storefront'
AND NOT EXISTS { MATCH (:Deployment)-[:Manages]->(:ReplicaSet)-[:Manages]->(p) }
AND NOT EXISTS { MATCH (:StatefulSet)-[:Manages]->(p) }
AND NOT EXISTS { MATCH (:DaemonSet)-[:Manages]->(p) }
AND NOT EXISTS { MATCH (:Job)-[:Manages]->(p) }
AND NOT EXISTS { MATCH (:ReplicaSet)-[:Manages]->(p) }
RETURN p['metadata']['name'] AS pod_name,
       p['status']['phase'] AS phase,
       p['metadata']['creationTimestamp'] AS created_at
ORDER BY pod_name

